import{_ as n}from"./chunks/weihnachtssteuerung-card.qFlEh_04.js";import{_ as t,o as i,c as a,a3 as r}from"./chunks/framework.BlfGB29P.js";const b=JSON.parse('{"title":"Festtags-Card-Editor","description":"Weihnachtssteuerung mit fünf Zeitplänen, Festtagsbildern, GIF-Dekoration und Schneefall.","frontmatter":{"title":"Festtags-Card-Editor","description":"Weihnachtssteuerung mit fünf Zeitplänen, Festtagsbildern, GIF-Dekoration und Schneefall."},"headers":[],"relativePath":"projects/festtags-card-editor/index.md","filePath":"projects/festtags-card-editor/index.md","lastUpdated":1795861737000}'),s={name:"projects/festtags-card-editor/index.md"};function l(d,e,o,h,u,c){return i(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="festtags-card-editor" tabindex="-1">Festtags-Card-Editor <a class="header-anchor" href="#festtags-card-editor" aria-label="Permalink to &quot;Festtags-Card-Editor&quot;">​</a></h1><p><strong>Version 0.1.12</strong> · Editor DE/EN · Dokumentation DE/EN/FR.</p><p><a href="/en/projects/festtags-card-editor/">English</a> · <a href="/fr/projects/festtags-card-editor/">Français</a></p><p><img src="'+n+`" alt="Weihnachtssteuerung mit eigenem Hintergrund, Schneefall und zwei Lichtsteuerungen"></p><p>Beispiel aus einem eingerichteten Dashboard. Das Hintergrundmotiv wird vom Nutzer bereitgestellt und gehört nicht zum App-Paket. Die Schneefallbewegung ist im Bildschirmfoto nicht sichtbar.</p><h2 id="funktionen" tabindex="-1">Funktionen <a class="header-anchor" href="#funktionen" aria-label="Permalink to &quot;Funktionen&quot;">​</a></h2><ul><li>Region und Land auswählen: 47 Länder und eigene Termine, westliche/julianische Traditionen.</li><li>Bis zu fünf Ziele (<code>light</code>, <code>switch</code>, <code>input_boolean</code>), jeweils mit eigener Ein-/Ausschaltzeit.</li><li>Täglich im Zeitraum oder nur an ausgewählten Festtagen; Jahreswechsel und Advent werden automatisch berechnet.</li><li>Vorgabe: 1. Advent bis einschließlich 10. Januar. Pausenschalter erhalten ihren Zustand nach Neustart.</li><li>Sensoren für aktuelle/nächste Festtage und nächste Schaltung; eigene Dashboard-Card.</li><li>Optionales Statussymbol: <code>mdi:lightbulb</code> für Ein, <code>mdi:lightbulb-outline</code> für Aus. Anzeige folgt dem tatsächlichen Zielzustand.</li></ul><p>Die Länderlisten sind Vorschläge für Fest- und Brauchtumstage, kein vollständiger gesetzlicher Feiertagskalender.</p><ol><li>und 2. Weihnachtstag, Stephanstag, Sinterklaas, Pakjesavond, Heilige Drei Könige und Epiphanias sind separate Einträge. Einige liegen am selben Tag.</li></ol><h2 id="installation-und-update" tabindex="-1">Installation und Update <a class="header-anchor" href="#installation-und-update" aria-label="Permalink to &quot;Installation und Update&quot;">​</a></h2><ol><li>Vollständiges HA-Backup erstellen und das <a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons" target="_blank" rel="noreferrer">UGSo-App-Repository</a> hinzufügen/aktualisieren.</li><li><strong>Festtags-Card-Editor</strong> installieren bzw. aktualisieren und starten. Architekturen: aarch64 und amd64.</li><li><strong>Home Assistant vollständig neu starten</strong>, nicht nur die Editor-App. Dadurch wird die aktualisierte Integration geladen.</li><li>Editor öffnen. Bei Erstinstallation <strong>Integration einrichten</strong> wählen. Region/Land, Ziele und Zeiten einstellen und speichern.</li><li><strong>Card-Ressource einrichten</strong> anklicken und das Dashboard vollständig neu laden.</li></ol><div class="language-yaml vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">type</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">custom:weihnachtssteuerung-card</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">title</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">Weihnachtssteuerung</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>Bestehende Einstellungen und Nutzerbilder bleiben erhalten. Die Steuerung läuft im HA-Core weiter, wenn die Editor-App gestoppt wird. Der Editor ist für HA-Administratoren über Ingress erreichbar. Die Entitätsauswahl lässt sich nach Name, ID, Bereich und Gerät durchsuchen.</p><h2 id="eigene-bilder-und-hintergrunde" tabindex="-1">Eigene Bilder und Hintergründe <a class="header-anchor" href="#eigene-bilder-und-hintergrunde" aria-label="Permalink to &quot;Eigene Bilder und Hintergründe&quot;">​</a></h2><p>Es werden keine Bilder mitgeliefert. Nur eigene Dateien mit passenden Nutzungsrechten verwenden.</p><div class="ugso-table-scroll" tabindex="0"><table><thead><tr><th>Zweck</th><th>HA-Ordner</th><th>URL-Pfad</th></tr></thead><tbody><tr><td>Festtagsbilder pro Land/Tag</td><td><code>/config/www/weihnachtssteuerung/bilder</code></td><td><code>/local/weihnachtssteuerung/bilder</code></td></tr><tr><td>Hintergründe und Dekorationen</td><td><code>/config/www/weihnachtssteuerung/background</code></td><td><code>/local/weihnachtssteuerung/background</code></td></tr></tbody></table></div><p>PNG, JPG, WebP und GIF hochladen (maximal 5 MiB/16 Megapixel); Animationen bleiben unverändert. Vorhandene SVG-Dateien können zugeordnet, aber nicht hochgeladen werden. Doppelte Dateinamen werden ergänzt, nicht überschrieben. <strong>Lösen</strong> bzw. <strong>Keine Datei</strong> entfernt nur die Zuordnung.</p><p>Festtagsbilder erscheinen in der Card 110 px hoch, proportional skaliert; Vorschau im Editor 90 × 90 px. Mehrere Motive können gleichzeitig erscheinen. Hintergrund und Dekoration lassen sich getrennt mit Transparenz, Größe und X/Y-Position einstellen. 0 % Transparenz = sichtbar, 100 % = unsichtbar; X/Y 0/0 = links oben, 100/100 = rechts unten. Abdunklung verbessert die Lesbarkeit. Texte und Buttons bleiben über den Effekten bedienbar.</p><h2 id="schneefall" tabindex="-1">Schneefall <a class="header-anchor" href="#schneefall" aria-label="Permalink to &quot;Schneefall&quot;">​</a></h2><ul><li>Modus <strong>Schneefall</strong> oder <strong>Bild + Schneefall</strong> wählen. Eine separate GIF-Dekoration kann zusätzlich aktiv sein.</li><li>6–40 Flocken; tatsächlicher Kreisdurchmesser 1–20 CSS-Pixel, Standard 4 px.</li><li><strong>Schneefall trotzdem animieren</strong> ist eine bewusste Ausnahme von <strong>Bewegung reduzieren</strong>, nur für diese Card. Standardmäßig ausgeschaltet.</li><li>Außerhalb des sichtbaren Bereichs und bei ausgeblendeter Seite pausiert die Animation weiterhin.</li><li>Nach Konfiguration speichern; für geänderte Card-Dateien die Ressource einrichten und Dashboard neu laden.</li></ul><h2 id="bestatigter-chrome-test-am-25-november-2026" tabindex="-1">Bestätigter Chrome-Test am 25. November 2026 <a class="header-anchor" href="#bestatigter-chrome-test-am-25-november-2026" aria-label="Permalink to &quot;Bestätigter Chrome-Test am 25. November 2026&quot;">​</a></h2><p>Auf einer HA-Installation mit Card <strong>0.1.12</strong> wurden ein geladenes GIF und <strong>30 gleichzeitig animierte Schneeflocken</strong> bestätigt. Die Flockenposition änderte sich zwischen zwei Beobachtungen; Animation <code>snow-fall</code>, Zustand <code>running</code>. Es wurden bei diesem Kombinationstest keine Einstellungen geändert. Dies ist kein allgemeiner Leistungstest für alle Tablets.</p><p><strong>Wenn Firefox animiert und Chrome nicht:</strong> Im beobachteten Fall lud Chrome noch die Ressource von <strong>0.1.8</strong>. Ein Neuladen allein ersetzte den alten Ressourcenverweis nicht. Im aktuellen Editor <strong>Card-Ressource einrichten</strong> ausführen, dann das Dashboard vollständig neu laden. Zusätzlich muss bei aktivem Bewegung reduzieren die Ausnahme gespeichert sein. Die sichtbare Card pausiert nicht mehr, sobald die aktuelle Datei und die ausdrückliche Ausnahme wirksam sind.</p><h2 id="links" tabindex="-1">Links <a class="header-anchor" href="#links" aria-label="Permalink to &quot;Links&quot;">​</a></h2><ul><li><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/festtags-card-editor-v0.1.12" target="_blank" rel="noreferrer">Release mit ZIPs</a></li><li><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/tree/master/festtags_card_editor" target="_blank" rel="noreferrer">Quellcode und ausführliche Anleitung</a></li><li><a href="/projects-mqtt/">UGSo HA Apps</a></li></ul>`,25)])])}const m=t(s,[["render",l]]);export{b as __pageData,m as default};
